/**
 * OWNED BY WP-02. Samples offered in the clinic dropzone ("Probar con un ejemplo"). The id equals the SeedCase key.
 * The sha256 values live in sample-hashes.json, rewritten by `npm run pdfs`, so they cannot drift from the
 * committed PDFs (tests/seed/pdfs.test.ts asserts it). They key WP-03's cached extraction fallback.
 */
import type { CaseKind } from "@/contracts";
import hashes from "./sample-hashes.json";

export interface SamplePdf {
  id: string;
  caseKind: CaseKind;
  label: { es: string; en: string };
  /** URL path under /public (the file itself is generated by `npm run pdfs`). */
  path: string;
  /** Hex sha256 of the committed PDF bytes; keys WP-03's cached fallback. */
  sha256: string;
}

const sha = (id: keyof typeof hashes): string => hashes[id];

export const SAMPLE_PDFS: SamplePdf[] = [
  {
    id: "implant-ribera",
    caseKind: "implant",
    label: { es: "Implantes · Clínica Dental Ribera (ficticio)", en: "Implants · Clínica Dental Ribera (synthetic)" },
    path: "/samples/presupuesto-implantes-ribera.pdf",
    sha256: sha("implant-ribera"),
  },
  {
    id: "aligner-ribera",
    caseKind: "aligner",
    label: {
      es: "Ortodoncia invisible · Clínica Dental Ribera (ficticio)",
      en: "Clear aligners · Clínica Dental Ribera (synthetic)",
    },
    path: "/samples/presupuesto-ortodoncia-ribera.pdf",
    sha256: sha("aligner-ribera"),
  },
  {
    id: "perio-ribera",
    caseKind: "perio",
    label: {
      es: "Periodoncia e implantes · Clínica Dental Ribera (ficticio)",
      en: "Gum care and implants · Clínica Dental Ribera (synthetic)",
    },
    path: "/samples/presupuesto-perio-implantes.pdf",
    sha256: sha("perio-ribera"),
  },
];

/** File name under public/samples/ for a sample id (used by the generator and the tests). */
export function sampleFileName(sample: Pick<SamplePdf, "path">): string {
  return sample.path.replace(/^\/samples\//, "");
}
